@'
import re, collections

path = r"text.gcode"
extrusion_z = collections.Counter()
cur_z = None
obj_markers = []
with open(path, 'r', errors='replace') as f:
    for i, raw in enumerate(f, 1):
        line = raw.strip()
        if not line:
            continue
        if line.startswith('M486'):
            m = re.search(r'M486 S(-?\d+)', line)
            if m:
                obj_markers.append((i, int(m.group(1))))
        if line[0] in 'G':
            has_e = 'E' in line
            mz = re.search(r'Z([-\d.]+)', line)
            if mz:
                cur_z = float(mz.group(1))
            if has_e and cur_z is not None and 'E-' not in line:
                m = re.search(r'E([\d.]+)', line)
                if m and float(m.group(1)) > 0:
                    extrusion_z[cur_z] += 1
print("distinct Z with positive-E G moves:", len(extrusion_z))
for z in sorted(extrusion_z):
    print(f"Z={z:8.3f}  moves={extrusion_z[z]}")
print("M486 markers:", obj_markers[:40])
